//! Ed25519 tests: commonware's scheme, core, batch, and lib tests, the RFC 8032, Wycheproof,
//! and ZIP-215 vectors, keys and signatures generated by commonware itself, and the
//! `ed25519_decode` / `ed25519_batch_verifier` fuzz targets (differential against
//! `std.crypto.sign.Ed25519`, whose strict rules accept a subset of ZIP-215).

const std = @import("std");
const parallel = @import("parallel");
const testing = std.testing;
const codec = @import("codec");
const utils = @import("utils");
const ed25519 = @import("../ed25519.zig");
const signer = @import("../signer.zig");
const fuzz = @import("../fuzz.zig");
const vectors = @import("vectors.zig");

const PrivateKey = ed25519.PrivateKey;
const PublicKey = ed25519.PublicKey;
const Signature = ed25519.Signature;
const Entry = PublicKey.Entry;
const StdEd25519 = std.crypto.sign.Ed25519;

fn hex(comptime n: usize, text: []const u8) [n]u8 {
    var out: [n]u8 = undefined;
    const decoded = std.fmt.hexToBytes(&out, text) catch unreachable; // Proof: test vectors.
    std.debug.assert(decoded.len == n);
    return out;
}

fn hex_slice(buffer: []u8, text: []const u8) []u8 {
    return std.fmt.hexToBytes(buffer, text) catch unreachable; // Proof: test vectors.
}

/// `PrivateKey::random(test_rng())`.
fn test_key() PrivateKey {
    var rng = utils.rng.test_rng();
    return PrivateKey.random(&rng);
}

fn decode(comptime T: type, bytes: []const u8) !T {
    return codec.decode(T, testing.allocator, bytes);
}

test "ed25519 RFC 8032 vectors" {
    var message_buffer: [1024]u8 = undefined;
    for (vectors.rfc8032) |vector| {
        const key = try decode(PrivateKey, &hex(32, vector.secret_key));
        const public_key = key.public_key();
        try testing.expectEqualSlices(u8, &hex(32, vector.public_key), public_key.as_slice());
        const message = hex_slice(&message_buffer, vector.message);
        const signature = key.sign_raw(message);
        try testing.expectEqualSlices(u8, &hex(64, vector.signature), &signature.raw);
        const decoded = try decode(PublicKey, &hex(32, vector.public_key));
        try testing.expect(public_key.verify_raw(message, &signature));
        try testing.expect(decoded.verify_raw(message, &signature));
        // Sanity: another key's signature and another message are rejected.
        const other = test_key().sign_raw(message);
        try testing.expect(!decoded.verify_raw(message, &other));
        try testing.expect(!decoded.verify_raw("this is a different message", &signature));
    }
}

test "ed25519 Wycheproof vectors under ZIP-215" {
    var message_buffer: [4096]u8 = undefined;
    var signature_buffer: [512]u8 = undefined;
    for (vectors.wycheproof) |vector| {
        const public_key = try decode(PublicKey, &hex(32, vector.public_key));
        const message = hex_slice(&message_buffer, vector.message);
        const raw = hex_slice(&signature_buffer, vector.signature);
        const signature = decode(Signature, raw) catch {
            try testing.expect(!vector.valid_zip215);
            continue;
        };
        const valid = public_key.verify_raw(message, &signature);
        try testing.expectEqual(vector.valid_zip215, valid);
    }
}

const zip215_namespace = "_COMMONWARE_CRYPTOGRAPHY_CURVE25519_ZIP215_VECTORS";
const zip215_message = "Zcash";

test "ed25519 ZIP-215 vectors, alone and in batches" {
    const count = vectors.zip215_points.len * vectors.zip215_points.len;
    var keys: [count]PublicKey = undefined;
    var signatures: [count]Signature = undefined;
    var batch: [count]Entry = undefined;
    var rng = utils.rng.test_rng();
    var index: usize = 0;
    for (vectors.zip215_points) |a| {
        for (vectors.zip215_points) |r| {
            keys[index] = try decode(PublicKey, &hex(32, a));
            signatures[index] = .{ .raw = hex(32, r) ++ @as([32]u8, @splat(0)) };
            const signature = &signatures[index];
            try testing.expect(keys[index].verify(zip215_namespace, zip215_message, signature));
            batch[index] = .{
                .namespace = zip215_namespace,
                .message = zip215_message,
                .public_key = &keys[index],
                .signature = &signatures[index],
            };
            const one = batch[index..][0..1];
            const sequential = parallel.sequential;
            try testing.expect(PublicKey.verify_batch(&rng, one, signer.entries, sequential));
            index += 1;
        }
    }
    try testing.expectEqual(@as(usize, 196), count);
    try testing.expect(PublicKey.verify_batch(&rng, &batch, signer.entries, parallel.sequential));
}

test "ed25519 codec round trips" {
    const key = try decode(PrivateKey, &hex(32, vectors.rfc8032[0].secret_key));
    const encoded_key = codec.encode_fixed(PrivateKey, key);
    try testing.expect(key.eql(&try decode(PrivateKey, &encoded_key)));
    const public_key = key.public_key();
    const encoded_public = codec.encode_fixed(PublicKey, public_key);
    try testing.expectEqualSlices(u8, &hex(32, vectors.rfc8032[0].public_key), &encoded_public);
    try testing.expect(public_key.eql(try decode(PublicKey, &encoded_public)));
    const signature = key.sign("namespace", "message");
    const encoded_signature = codec.encode_fixed(Signature, signature);
    try testing.expect(signature.eql(try decode(Signature, &encoded_signature)));
    try testing.expectEqual(@as(?usize, 32), codec.fixed_size(PublicKey));
    try testing.expectEqual(@as(?usize, 64), codec.fixed_size(Signature));
}

