test "ed25519 signer contract (lib tests)" {
    const namespace = "test_namespace";
    const message = "test_message";
    var rng = utils.rng.test_rng();
    const key = PrivateKey.random(&rng);
    const public_key = key.public_key();
    const decoded = try decode(PublicKey, public_key.as_slice());
    try testing.expect(public_key.eql(decoded));
    try testing.expectEqual(std.math.Order.eq, public_key.order(decoded));
    try testing.expect(!public_key.eql(PrivateKey.random(&rng).public_key()));
    const zeroes: [1024]u8 = @splat(0);
    try testing.expectError(error.ExtraData, decode(PublicKey, &zeroes));

    const signing = PrivateKey.from_seed(0);
    const signature = signing.sign(namespace, message);
    try testing.expect(signing.public_key().verify(namespace, message, &signature));
    try testing.expect(!signing.public_key().verify(namespace, "wrong_message", &signature));
    try testing.expect(!signing.public_key().verify("wrong_namespace", message, &signature));
    const empty = signing.sign("", message);
    try testing.expect(signing.public_key().verify("", message, &empty));
    try testing.expect(!signing.public_key().verify_raw(message, &signature));
    try testing.expect(signature.eql(PrivateKey.from_seed(0).sign(namespace, message)));
    const other = PrivateKey.from_seed(1).public_key();
    try testing.expect(!other.verify(namespace, message, &signature));
    try testing.expect(PrivateKey.from_seed(0).public_key().eql(signing.public_key()));
}

test "ed25519 rejects zero, high-s, and invalid-R signatures" {
    const vector = vectors.rfc8032[0];
    const public_key = try decode(PublicKey, &hex(32, vector.public_key));
    const zero: Signature = .{ .raw = @splat(0) };
    try testing.expect(!public_key.verify_raw("", &zero));
    var high_s: Signature = .{ .raw = hex(64, vector.signature) };
    try testing.expect(public_key.verify_raw("", &high_s));
    high_s.raw[63] |= 0x80;
    try testing.expect(!public_key.verify_raw("", &high_s));
    var invalid_r: Signature = .{ .raw = hex(64, vector.signature) };
    @memset(invalid_r.raw[0..32], 0xff);
    try testing.expect(!public_key.verify_raw("", &invalid_r));
}

test "ed25519 distinct encodings of one point are distinct keys" {
    var canonical: [32]u8 = @splat(0);
    canonical[0] = 1;
    var noncanonical: [32]u8 = @splat(0xff);
    noncanonical[0] = 0xee;
    noncanonical[31] = 0x7f;
    const a = try decode(PublicKey, &canonical);
    const b = try decode(PublicKey, &noncanonical);
    try testing.expect(a.key.minus_a.toBytes()[0] == b.key.minus_a.toBytes()[0]);
    try testing.expect(std.mem.eql(u8, &a.key.minus_a.toBytes(), &b.key.minus_a.toBytes()));
    try testing.expect(!a.eql(b));
    try testing.expect(a.order(b) != .eq);
}

test "ed25519 private key is redacted" {
    var buffer: [64]u8 = undefined;
    const key = test_key();
    try testing.expectEqualStrings("[REDACTED]", try std.fmt.bufPrint(&buffer, "{f}", .{key}));
}

// commonware `test_from_signing_key`: `From<SigningKey>` is the struct literal here.
test "ed25519 private key from a core signing key" {
    var rng = utils.rng.test_rng();
    var seed: [32]u8 = undefined;
    rng.fill_bytes(&seed);
    const signing_key = ed25519.core.SigningKey.from_seed(seed);
    const expected = signing_key.verification_key.bytes;
    const private_key: PrivateKey = .{ .key = signing_key };
    try testing.expectEqualSlices(u8, &expected, &private_key.public_key().key.bytes);
    try testing.expect(private_key.eql(&test_key()));
}

/// Signs `count` 32-byte random messages with each of `signers` keys from `test_rng`.
const Fixture = struct {
    const capacity = 160;
    keys: [capacity]PublicKey = undefined,
    signatures: [capacity]Signature = undefined,
    messages: [capacity][32]u8 = undefined,
    count: usize = 0,

    fn init(signers: usize, per_signer: usize) Fixture {
        std.debug.assert(signers * per_signer <= capacity);
        var fixture: Fixture = .{};
        var rng = utils.rng.test_rng();
        for (0..signers) |_| {
            const key = PrivateKey.random(&rng);
            for (0..per_signer) |_| {
                rng.fill_bytes(&fixture.messages[fixture.count]);
                fixture.keys[fixture.count] = key.public_key();
                fixture.signatures[fixture.count] = key.sign_raw(&fixture.messages[fixture.count]);
                fixture.count += 1;
            }
        }
        return fixture;
    }

    fn verify(fixture: *const Fixture) !bool {
        const Op = struct {
            fixture: *const Fixture,
            pub fn run(op: @This(), explorer: parallel.mocks.Explorer) bool {
                return op.fixture.verify_with(explorer);
            }
        };
        const verdict = try parallel.mocks.explore(testing.allocator, testing.io, Op{
            .fixture = fixture,
        });
        try testing.expectEqual(fixture.verify_with(parallel.sequential), verdict);
        return verdict;
    }

    /// The verdict under `strategy`; `verify` checks every strategy shape agrees.
    fn verify_with(fixture: *const Fixture, strategy: anytype) bool {
        var items: [capacity]ed25519.core.BatchItem = undefined;
        for (0..fixture.count) |i| {
            items[i] = .{
                .key = &fixture.keys[i].key,
                .signature = &fixture.signatures[i].raw,
                .namespace = null,
                .message = &fixture.messages[i],
            };
        }
        const Items = struct {
            items: []const ed25519.core.BatchItem,
            pub fn item(self: @This(), index: usize) ed25519.core.BatchItem {
                return self.items[index];
            }
        };
        var rng = utils.rng.test_rng();
        const view = Items{ .items = items[0..fixture.count] };
        return ed25519.core.verify_batch(&rng, fixture.count, view, strategy);
    }
};

test "ed25519 batch rejects each altered item in every shape" {
    for (1..4) |signers| {
        for (1..4) |per_signer| {
            const valid = Fixture.init(signers, per_signer);
            try testing.expect(try valid.verify());
            for (0..valid.count) |altered| {
                var items = valid;
                items.messages[altered][0] ^= 1;
                try testing.expect(!try items.verify());
            }
        }
    }
    // Interleaved duplicate keys, and a batch larger than one multiscalar chunk.
    var many = Fixture.init(4, 8);
    try testing.expect(try many.verify());
    many.messages[29][0] ^= 1;
    try testing.expect(!try many.verify());
    // Past the Straus cutoff a whole batch is two bucket chunks of 65, one key straddling them.
    const large = Fixture.init(13, 10);
    comptime std.debug.assert(130 > ed25519.msm.chunk_signatures);
    try testing.expect(try large.verify());
    for ([_]usize{ 0, 64, 65, 129 }) |altered| {
        var items = large;
        items.messages[altered][0] ^= 1;
        try testing.expect(!try items.verify());
    }
}

test "ed25519 batch framing matches union_unique" {
    const key = test_key();
    const public_key = key.public_key();
    var rng = utils.rng.test_rng();
    var namespace: [16384]u8 = @splat(42);
    var moved: [16384 + 7]u8 = undefined;
    for ([_]usize{ 0, 1, 127, 128, 255, 16383, 16384 }) |length| {
        const ns = namespace[0..length];
        const payload = try utils.union_unique(testing.allocator, ns, "message");
        defer testing.allocator.free(payload);
        const signature = key.sign_raw(payload);
        for ([_][]const u8{ ns, "other" }) |supplied| {
            const entry: [1]Entry = .{.{
                .namespace = supplied,
                .message = "message",
                .public_key = &public_key,
                .signature = &signature,
            }};
            const expected = std.mem.eql(u8, supplied, ns);
            const valid = PublicKey.verify_batch(&rng, &entry, signer.entries, parallel.sequential);
            try testing.expectEqual(expected, valid);
        }
        if (length == 0) continue;
        // Moving a byte across the namespace boundary invalidates the signature.
        moved[0] = ns[length - 1];
        @memcpy(moved[1..8], "message");
        const entry: [1]Entry = .{.{
            .namespace = ns[0 .. length - 1],
            .message = moved[0..8],
            .public_key = &public_key,
            .signature = &signature,
        }};
        const sequential = parallel.sequential;
        try testing.expect(!PublicKey.verify_batch(&rng, &entry, signer.entries, sequential));
    }
}

test "ed25519 projected batch over records, empty, and noncanonical s" {
    const Record = struct { message: [1024]u8, length: usize, signature: Signature, signer: usize };
    var rng = utils.rng.test_rng();
    const keys = [2]PrivateKey{ PrivateKey.random(&rng), PrivateKey.random(&rng) };
    const publics = [2]PublicKey{ keys[0].public_key(), keys[1].public_key() };
    var records: [25]Record = undefined;
    for (&records, 0..) |*record, i| {
        record.length = if (i % 3 == 0) 0 else 1024;
        @memset(&record.message, @truncate(i));
        record.signer = i % 2;
        record.signature = keys[i % 2].sign("namespace", record.message[0..record.length]);
    }
    const Projector = struct {
        publics: *const [2]PublicKey,
        records: []const Record,
        pub fn project(self: @This(), index: usize, record: *const Record) Entry {
            std.debug.assert(record == &self.records[index]);
            return .{
                .namespace = "namespace",
                .message = record.message[0..record.length],
                .public_key = &self.publics[record.signer],
                .signature = &record.signature,
            };
        }
    };
    const projector = Projector{ .publics = &publics, .records = &records };
    const all: []const Record = &records;
    // Every strategy shape reaches the sequential verdict (commonware explores them all).
    const Op = struct {
        records: []const Record,
        projector: Projector,
        pub fn run(op: @This(), explorer: parallel.mocks.Explorer) bool {
            var op_rng = utils.rng.test_rng();
            return PublicKey.verify_batch(&op_rng, op.records, op.projector, explorer);
        }
    };
    const op = Op{ .records = all, .projector = projector };
    try testing.expect(try parallel.mocks.explore(testing.allocator, testing.io, op));
    try testing.expect(PublicKey.verify_batch(&rng, all, projector, parallel.sequential));
    for (0..records.len) |index| {
        records[index].message[0] ^= 1;
        if (records[index].length == 0) records[index].length = 1;
        try testing.expect(!PublicKey.verify_batch(&rng, all, projector, parallel.sequential));
        try testing.expect(!try parallel.mocks.explore(testing.allocator, testing.io, op));
        records[index].message[0] ^= 1;
        if (index % 3 == 0) records[index].length = 0;
    }
    records[24].signature.raw[63] |= 0x80;
    try testing.expect(!PublicKey.verify_batch(&rng, all, projector, parallel.sequential));
    const empty: []const Entry = &.{};
    try testing.expect(!PublicKey.verify_batch(&rng, empty, signer.entries, parallel.sequential));
}

/// The `ed25519_decode` fuzz target: decoding, verification, and signing agree with
/// `std.crypto.sign.Ed25519` wherever its strict rules accept the input.
fn fuzz_decode(bytes: []const u8) !void {
    var input = fuzz.Input.init(bytes);
    const selector = input.int_in_range(0, 3);
    var fixed: [96]u8 = undefined;
    input.fill(&fixed);
    const split = input.int_in_range(0, 255);
    const rest = input.bytes;
    const namespace = rest[0..@min(split, rest.len)];
    const message = rest[namespace.len..];
    switch (selector) {
        0 => {
            const key = decode(PublicKey, fixed[0..32]) catch {
                // ZIP-215 decoding is the more lenient, so std rejects whatever it rejects.
                const strict = std.crypto.ecc.Edwards25519.fromBytes(fixed[0..32].*);
                if (strict) |_| return error.TestUnexpectedResult else |_| return;
            };
            try testing.expectEqualSlices(u8, fixed[0..32], &codec.encode_fixed(PublicKey, key));
        },
        1 => {
            const signature = try decode(Signature, fixed[0..64]);
            const encoded = codec.encode_fixed(Signature, signature);
            try testing.expectEqualSlices(u8, fixed[0..64], &encoded);
            try testing.expectError(error.EndOfBuffer, decode(Signature, fixed[0..63]));
        },
        2 => {
            const public_key = decode(PublicKey, fixed[0..32]) catch return;
            const signature: Signature = .{ .raw = fixed[32..96].* };
            const ours = public_key.verify_raw(message, &signature);
            const std_key = StdEd25519.PublicKey.fromBytes(fixed[0..32].*) catch return;
            const std_signature = StdEd25519.Signature.fromBytes(fixed[32..96].*);
            if (std_signature.verify(message, std_key)) |_| try testing.expect(ours) else |_| {}
        },
        else => {
            const key = PrivateKey.from_bytes(fixed[0..32].*);
            const std_pair = try StdEd25519.KeyPair.generateDeterministic(fixed[0..32].*);
            const std_public = std_pair.public_key.toBytes();
            try testing.expectEqualSlices(u8, &std_public, key.public_key().as_slice());
            const payload = try utils.union_unique(testing.allocator, namespace, message);
            defer testing.allocator.free(payload);
            const std_signature = try std_pair.sign(payload, null);
            const signature = key.sign(namespace, message);
            try testing.expectEqualSlices(u8, &std_signature.toBytes(), &signature.raw);
            try testing.expect(key.public_key().verify(namespace, message, &signature));
            try testing.expect(key.public_key().verify_raw(payload, &signature));
        },
    }
}

test "ed25519 fuzz decode (seeded)" {
    var random = fuzz.prng(0xed25519);
    var bytes: [512]u8 = undefined;
    for (0..fuzz.iterations(256)) |_| {
        random.random().bytes(&bytes);
        try fuzz_decode(bytes[0..random.random().uintAtMost(usize, bytes.len)]);
    }
    // Small-order and non-canonical keys from ZIP-215 through every path.
    for (vectors.zip215_points) |point| {
        var input: [97]u8 = undefined;
        input[0] = 2;
        input[1..33].* = hex(32, point);
        @memset(input[33..], 0);
        try fuzz_decode(&input);
        input[0] = 0;
        try fuzz_decode(&input);
    }
}

test "ed25519 fuzz decode (coverage-guided)" {
    try testing.fuzz({}, struct {
        fn run(_: void, smith: *testing.Smith) anyerror!void {
            var bytes: [512]u8 = undefined;
            const length = smith.slice(&bytes);
            try fuzz_decode(bytes[0..length]);
        }
    }.run, .{});
}

/// The `ed25519_batch_verifier` fuzz target: batches of valid and wrong-key signatures
/// verify exactly when every entry is valid, on any strategy.
fn fuzz_batch(bytes: []const u8, strategy: anytype) !void {
    const capacity = 32;
    var input = fuzz.Input.init(bytes);
    var rng = utils.rng.TestRng.init(input.int_in_range(0, std.math.maxInt(u64)));
    var keys: [capacity]PublicKey = undefined;
    var signatures: [capacity]Signature = undefined;
    var messages: [capacity][16]u8 = undefined;
    var batch: [capacity]Entry = undefined;
    var count: usize = 0;
    var expected: ?bool = null;
    const operations = input.int_in_range(1, capacity);
    for (0..operations + 1) |step| {
        const operation = if (step == operations) 2 else input.int_in_range(0, 2);
        if (operation == 2) {
            const valid = PublicKey.verify_batch(&rng, batch[0..count], signer.entries, strategy);
            try testing.expectEqual(expected orelse false, valid);
            count = 0;
            expected = null;
            continue;
        }
        const key = PrivateKey.from_seed(input.int_in_range(0, 7));
        input.fill(&messages[count]);
        signatures[count] = key.sign("namespace", &messages[count]);
        keys[count] = key.public_key();
        if (operation == 1) {
            const wrong = PrivateKey.from_seed(8 + input.int_in_range(0, 7));
            keys[count] = wrong.public_key();
            const signature = &signatures[count];
            try testing.expect(!keys[count].verify("namespace", &messages[count], signature));
        }
        batch[count] = .{
            .namespace = "namespace",
            .message = &messages[count],
            .public_key = &keys[count],
            .signature = &signatures[count],
        };
        count += 1;
        expected = (expected orelse true) and operation == 0;
    }
}

test "ed25519 fuzz batch verifier (seeded)" {
    // A pool splits batches into shards with their own coefficients; the verdict must match.
    const pool = try parallel.ThreadPool.create(testing.allocator, testing.io, .{ .threads = 3 });
    defer pool.destroy();
    var random = fuzz.prng(0xba7c4);
    var bytes: [256]u8 = undefined;
    for (0..fuzz.iterations(16)) |_| {
        random.random().bytes(&bytes);
        const input = bytes[0..random.random().uintAtMost(usize, bytes.len)];
        try fuzz_batch(input, parallel.sequential);
        try fuzz_batch(input, parallel.Rayon.init(pool));
    }
}
